<script setup lang="ts">
import InfiniteList from './InfiniteList.vue'
import {computed,onMounted,onBeforeUnmount,reactive,ref} from 'vue'
import {appendUnique,api,body,list,type Row,APIError} from '../api'
import {randomID} from '../random'
import {confirmAction} from '../confirm'
import {toast} from '../toast'
import SelectField from './SelectField.vue'
const items=ref<Row[]>([]),loading=ref(true),busy=ref(false),reloading=ref(false),error=ref(''),conflict=ref(false),cursor=ref(''),more=ref(false),query=ref(''),filter=ref('all'),textInput=ref<HTMLTextAreaElement>()
const form=reactive({id:'',version:0,text:'',source:'',kind:'sentence',published:false})
const initial=ref('');let createKey=randomID()
const snapshot=()=>JSON.stringify({text:form.text,source:form.source,kind:form.kind,published:form.published})
initial.value=snapshot()
const dirty=computed(()=>snapshot()!==initial.value),length=computed(()=>Array.from(form.text).length),visible=computed(()=>items.value.filter(r=>(filter.value==='all'||r.published===(filter.value==='published'))&&(!query.value||(r.text+' '+r.source).toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))))
async function load(append=false){if(append&&(loading.value||busy.value||!cursor.value))return;loading.value=true;error.value='';try{const data=await api('/admin/phrases?limit=20'+(append?'&cursor='+encodeURIComponent(cursor.value):''));items.value=append?appendUnique(items.value,list(data)):list(data);cursor.value=data.next_cursor||'';more.value=data.has_more;return true}catch(e){error.value=(e as Error).message;return false}finally{loading.value=false}}
function fill(row?:Row){Object.assign(form,row?{id:row.id,version:row.version,text:row.text,source:row.source,kind:row.kind,published:row.published}:{id:'',version:0,text:'',source:'',kind:'sentence',published:false});initial.value=snapshot();createKey=randomID();conflict.value=false}
async function edit(row?:Row){if(busy.value)return;if(dirty.value&&!await confirmAction('放弃未保存的修改？','切换片语前，请确认当前内容已经保存。','放弃修改'))return;fill(row);error.value='';textInput.value?.focus()}
async function save(){if(busy.value||conflict.value)return;busy.value=true;error.value='';try{const data={text:form.text,kind:form.kind,source:form.source,published:form.published};const result=await api(form.id?'/admin/phrases/'+form.id:'/admin/phrases',{method:form.id?'PUT':'POST',...(form.id?{version:form.version}:{key:createKey}),body:body(data)});const index=items.value.findIndex(r=>r.id===result.id);if(index>=0)items.value[index]=result;else items.value.unshift(result);fill(result);toast.success(result.published?'片语已公开，可以在展示页读到。':'草稿已保存，仅站长可见。')}catch(e){conflict.value=!!form.id&&e instanceof APIError&&e.status===409;if(conflict.value||(e instanceof APIError&&e.code==='VALIDATION_FAILED'))error.value=(e as Error).message;else toast.error((e as Error).message)}finally{busy.value=false}}
async function reloadCurrent(){if(busy.value||!form.id)return;const id=form.id;busy.value=true;reloading.value=true;try{if(dirty.value&&!await confirmAction('载入服务器版本？','当前输入将被服务器最新内容替换。','载入最新'))return;error.value='';const latest=await api('/admin/phrases/'+encodeURIComponent(id));if(String(latest.id)!==id||!Number.isSafeInteger(Number(latest.version))||Number(latest.version)<1||typeof latest.text!=='string'||typeof latest.source!=='string'||!['sentence','word'].includes(latest.kind)||typeof latest.published!=='boolean')throw new Error('服务器片语数据不完整，当前输入已保留。');const index=items.value.findIndex(r=>r.id===id);if(index>=0)items.value[index]=latest;fill(latest);toast.success('已载入服务器最新版本。')}catch(e){error.value=e instanceof APIError&&e.status===404?'这条片语已删除，当前输入已保留。你可以复制内容后新建。':(e as Error).message;conflict.value=true}finally{busy.value=false;reloading.value=false}}
async function remove(row:Row){if(busy.value||!await confirmAction('删除这条片语？','删除后无法恢复，公开展示页也会移除它。','删除片语'))return;busy.value=true;error.value='';try{await api('/admin/phrases/'+row.id,{method:'DELETE',version:row.version});items.value=items.value.filter(r=>r.id!==row.id);if(form.id===row.id)fill();toast.success('片语已删除。')}catch(e){toast.error((e as Error).message)}finally{busy.value=false}}
function beforeLeave(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>{void load();window.addEventListener('beforeunload',beforeLeave)})
onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeLeave))
</script>
<template>
 <div class="phrase-management-toolbar"><p>短句与词语，构成文章之外的另一面。</p><a class="button" href="/phrases" target="_blank" rel="noopener">查看片语页<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M5 19 19 5M7 5h12v12"/></svg></a></div>
 <div v-if="error" class="notice error" role="alert">{{error}}<button v-if="conflict" type="button" class="quiet" :disabled="busy" @click="reloadCurrent">载入最新版本</button><button v-else type="button" class="quiet" :disabled="busy||loading" @click="load()">刷新列表</button></div>
 <div class="phrase-management"><form class="panel phrase-composer" @submit.prevent="save"><div class="phrase-composer-heading"><h2>{{form.id?'编辑片语':'写一条片语'}}</h2><button v-if="form.id" type="button" class="quiet" :disabled="busy" @click="edit()">新建</button></div><p v-if="dirty" class="phrase-unsaved" role="status">有未保存的修改</p><SelectField v-model="form.kind" label="内容类型" :disabled="busy" :options="[{value:'sentence',label:'句子'},{value:'word',label:'词语'}]"/><label for="phrase-text">{{form.kind==='word'?'词语':'句子'}}</label><textarea id="phrase-text" ref="textInput" v-model="form.text" rows="6" required :disabled="busy" aria-describedby="phrase-length" placeholder="留下一点此刻的想法…"></textarea><span id="phrase-length" class="phrase-length" :class="{danger:length>280}">{{length}} / 280 字</span><label for="phrase-source">来源或署名 <span class="muted">选填</span></label><input id="phrase-source" v-model="form.source" :disabled="busy" maxlength="120" placeholder="例如书名、作者，或留空"><label class="check phrase-publish"><input type="checkbox" v-model="form.published" :disabled="busy">在片语页公开展示</label><p class="muted">不勾选时保存为草稿，仅站长可见。</p><div class="form-actions"><button class="primary" :disabled="busy||loading||conflict||!form.text.trim()||length>280">{{reloading?'正在载入…':busy?'正在保存…':form.published?'保存并公开':'保存草稿'}}</button><button v-if="dirty" type="button" class="quiet" :disabled="busy" @click="edit()">取消修改</button></div></form>
 <section class="phrase-library" aria-label="片语列表"><div class="phrase-library-tools"><div class="tabs" aria-label="片语状态"><button v-for="f in [{id:'all',label:'全部'},{id:'published',label:'公开'},{id:'draft',label:'草稿'}]" :key="f.id" type="button" :class="{active:filter===f.id}" :aria-pressed="filter===f.id" @click="filter=f.id">{{f.label}}</button></div><label class="sr-only" for="phrase-search">筛选已加载片语</label><input id="phrase-search" v-model="query" type="search" placeholder="筛选已加载的片语"></div><p v-if="loading" role="status" class="muted">正在加载片语…</p><div v-for="row in visible" :key="row.id" class="phrase-library-row" :class="{'is-editing':form.id===row.id}"><div class="phrase-row-meta"><span>{{row.kind==='word'?'词语':'句子'}}</span><span class="status" :class="{published:row.published}">{{row.published?'公开':'草稿'}}</span></div><p>{{row.text}}</p><span v-if="row.source" class="phrase-source">{{row.source}}</span><div class="phrase-row-actions"><button type="button" class="quiet" :disabled="busy" @click="edit(row)">{{form.id===row.id?'正在编辑':'编辑'}}</button><button type="button" class="quiet danger" :disabled="busy||loading" @click="remove(row)">删除</button></div></div><div v-if="!loading&&!visible.length" class="phrase-empty"><h2>{{items.length?'没有匹配的片语':'这里还没有片语'}}</h2><p>{{items.length?'试试其他关键词，或切换状态。':'从左侧写下一句话，保存为草稿或直接公开。'}}</p></div><InfiniteList :has-more="more" :loading="loading" :disabled="busy" :error="error" @load="load(true)"/></section></div>
</template>
